<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { getApiErrorMessage } from '../../services/http';
import { leadApi, type EmailAutomationFailure, type EmailAutomationReply, type EmailAutomationRun } from '../../services/leadApi';
import { displayFailureCompany, formatReplyAnalysis, previewReplyContent } from './emailAutomationPresentation.js';

const text = {
  title: '\u90ae\u4ef6\u81ea\u52a8\u89e6\u8fbe\u8fd0\u884c\u5386\u53f2', subtitle: '\u67e5\u770b\u6bcf\u8f6e\u89e6\u8fbe\u7684\u53d1\u9001\u7ed3\u679c\u4e0e\u5931\u8d25\u539f\u56e0', refresh: '\u5237\u65b0', loading: '\u8fd0\u884c\u5386\u53f2\u52a0\u8f7d\u4e2d\u2026', empty: '\u6682\u65e0\u8fd0\u884c\u5386\u53f2',
  start: '\u5f00\u59cb\u65f6\u95f4', status: '\u72b6\u6001', candidates: '\u5019\u9009', sent: '\u6210\u529f', failed: '\u5931\u8d25', replied: '\u5df2\u56de\u590d',
  detail: '\u67e5\u770b\u5931\u8d25\u660e\u7ec6', replyDetail: '\u67e5\u770b\u56de\u590d\u660e\u7ec6', noFail: '\u672c\u8f6e\u65e0\u5931\u8d25', noReply: '\u672c\u8f6e\u6682\u65e0\u5ba2\u6237\u56de\u590d', old: '\u8be5\u8f6e\u8fd0\u884c\u65e0\u5931\u8d25\u660e\u7ec6\uff08\u65e7\u6570\u636e\uff09',
  failCount: '\u6761\u5931\u8d25', replyCount: '\u6761\u56de\u590d', company: '\u516c\u53f8', contact: '\u8054\u7cfb\u4eba', email: '\u90ae\u7bb1', content: '\u90ae\u4ef6\u5185\u5bb9', analysis: '\u90ae\u4ef6\u5206\u6790',
  reason: '\u539f\u56e0', hint: '\u5efa\u8bae', copy: '\u590d\u5236', view: '\u67e5\u770b', close: '\u5173\u95ed', previous: '\u4e0a\u4e00\u9875', next: '\u4e0b\u4e00\u9875', subject: '\u4e3b\u9898', receivedAt: '\u63a5\u6536\u65f6\u95f4',
  intent: '\u56de\u590d\u610f\u56fe', nextAction: '\u4e0b\u4e00\u6b65\u5efa\u8bae', confidence: '\u7f6e\u4fe1\u5ea6', evidence: '\u5224\u65ad\u4f9d\u636e', unknown: '\u672a\u5206\u6790', action: '\u64cd\u4f5c',
};
const codeLabels: Record<string, string> = { TRANSLATION_SIGNATURE: '\u7b7e\u540d\u7f3a\u5931', TRANSLATION_INCOMPLETE: '\u7ffb\u8bd1\u4e0d\u5b8c\u6574', SMTP_REJECT: '\u670d\u52a1\u5668\u62d2\u6536', SMTP_CONNECTION: '\u8fde\u63a5\u5931\u8d25', PROVIDER_ERROR: '\u670d\u52a1\u5546\u9519\u8bef', HARD_BOUNCE: '\u786c\u9000\u4fe1', SOFT_BOUNCE: '\u8f6f\u9000\u4fe1', UNKNOWN: '\u53d1\u9001\u5931\u8d25', RUN_INTERRUPTED: '\u672c\u8f6e\u4e2d\u65ad' };

const runs = ref<EmailAutomationRun[]>([]); const loadingRuns = ref(true); const runsError = ref('');
const selectedRun = ref<EmailAutomationRun | null>(null); const selectedPanel = ref<'failures' | 'replies' | null>(null);
const failures = ref<EmailAutomationFailure[]>([]); const failureByCode = ref<Record<string, number>>({}); const failureCode = ref(''); const failurePage = ref(1); const failureTotal = ref(0); const failureLoading = ref(false); const failureError = ref(''); const failureUnavailable = ref(false);
const replies = ref<EmailAutomationReply[]>([]); const replyPage = ref(1); const replyTotal = ref(0); const replyLoading = ref(false); const replyError = ref(''); const selectedReply = ref<EmailAutomationReply | null>(null); const selectedFailure = ref<EmailAutomationFailure | null>(null);
const totalFailurePages = computed(() => Math.max(1, Math.ceil(failureTotal.value / 20))); const totalReplyPages = computed(() => Math.max(1, Math.ceil(replyTotal.value / 20)));
const labelForCode = (code: string) => codeLabels[code] || code;
const loadRuns = async () => { loadingRuns.value = true; runsError.value = ''; try { const result = await leadApi.listEmailAutomationRuns(100); runs.value = result?.items || []; } catch (error) { runsError.value = getApiErrorMessage(error, '运行历史加载失败'); } finally { loadingRuns.value = false; } };
const loadFailures = async (page = 1) => { if (!selectedRun.value) return; failureLoading.value = true; failureError.value = ''; try { const result = await leadApi.listEmailAutomationFailures(selectedRun.value.runId, { page, pageSize: 20, code: failureCode.value || undefined }); failures.value = result?.items || []; failureByCode.value = result?.byCode || {}; failureTotal.value = Number(result?.total || 0); failurePage.value = page; failureUnavailable.value = Boolean(result?.unavailable); } catch (error) { failureError.value = getApiErrorMessage(error, '失败明细加载失败'); } finally { failureLoading.value = false; } };
const loadReplies = async (page = 1) => { if (!selectedRun.value) return; replyLoading.value = true; replyError.value = ''; try { const result = await leadApi.listEmailAutomationReplies(selectedRun.value.runId, { page, pageSize: 20 }); replies.value = result?.items || []; replyTotal.value = Number(result?.total || 0); replyPage.value = page; } catch (error) { replyError.value = getApiErrorMessage(error, '回复明细加载失败'); } finally { replyLoading.value = false; } };
const togglePanel = async (run: EmailAutomationRun, panel: 'failures' | 'replies') => { if (selectedRun.value?.runId === run.runId && selectedPanel.value === panel) { selectedPanel.value = null; return; } selectedRun.value = run; selectedPanel.value = panel; selectedReply.value = null; selectedFailure.value = null; if (panel === 'failures') { failureCode.value = ''; failures.value = []; failureUnavailable.value = Boolean(run.failureSummary?.unavailable); await loadFailures(); } else { replies.value = []; await loadReplies(); } };
const filterCode = async (code: string) => { failureCode.value = failureCode.value === code ? '' : code; await loadFailures(1); };
const copyEmail = async (email?: string | null) => { if (!email) return; try { await navigator.clipboard.writeText(email); } catch { failureError.value = '邮箱复制失败，请手动复制'; } };
onMounted(() => { void loadRuns(); });
</script>
<template>
  <div class="content-main email-automation-page">
    <div class="dashboard-title-row"><div><div class="dashboard-title">{{ text.title }}</div><div class="dashboard-subtitle">{{ text.subtitle }}</div></div><div class="email-automation-header-actions"><button class="btn-xs" type="button" @click="loadRuns">{{ text.refresh }}</button><router-link class="btn-xs email-automation-close" to="/lead-analysis" aria-label="Close and return to lead analysis" title="Close">&#215;</router-link></div></div>
    <div v-if="loadingRuns" class="email-automation-state">{{ text.loading }}</div><div v-else-if="runsError" class="analysis-outreach-error" role="alert">{{ runsError }}</div><div v-else-if="!runs.length" class="email-automation-state">{{ text.empty }}</div>
    <section v-else class="panel email-automation-runs"><div class="table-scroll"><table class="matrix-table"><thead><tr><th>{{ text.start }}</th><th>{{ text.status }}</th><th>{{ text.candidates }}</th><th>{{ text.sent }}</th><th>{{ text.failed }}</th><th>{{ text.replied }}</th></tr></thead><tbody><template v-for="run in runs" :key="run.runId"><tr><td>{{ run.startedAt ? new Date(run.startedAt).toLocaleString() : '-' }}</td><td>{{ run.status }}</td><td>{{ run.candidates }}</td><td>{{ run.sent }}</td><td><button class="count-button" :class="run.failed ? 'has-failures' : 'zero-count'" type="button" :disabled="!run.failed" :title="text.detail" @click="togglePanel(run, 'failures')">{{ run.failed }}</button></td><td><button class="count-button" :class="run.deliverySummary?.replied ? 'has-replies' : 'zero-count'" type="button" :disabled="!run.deliverySummary?.replied" :title="text.replyDetail" @click="togglePanel(run, 'replies')">{{ run.deliverySummary?.replied || 0 }}</button></td></tr>
      <tr v-if="selectedRun?.runId === run.runId && selectedPanel === 'failures'"><td colspan="6" class="detail-cell"><div v-if="failureError" class="analysis-outreach-error" role="alert">{{ failureError }}</div><div v-if="failureUnavailable" class="email-automation-state">{{ text.old }}</div><template v-else><div class="detail-summary">{{ failureTotal }} {{ text.failCount }} <button v-for="(count, code) in failureByCode" :key="code" class="failure-code-chip" :class="{ active: failureCode === code }" type="button" @click="filterCode(code)">{{ labelForCode(code) }} ×{{ count }}</button></div><div v-if="failureLoading" class="email-automation-state">{{ text.loading }}</div><div v-else-if="!failures.length" class="email-automation-state">{{ text.noFail }}</div><table v-else class="detail-table"><thead><tr><th>{{ text.company }}</th><th>{{ text.contact }}</th><th>{{ text.email }}</th><th>{{ text.reason }}</th><th>{{ text.hint }}</th><th class="action-cell">{{ text.action }}</th></tr></thead><tbody><tr v-for="item in failures" :key="item.companyId + '-' + item.contactId + '-' + item.code"><td><div class="detail-cell-content">{{ displayFailureCompany(item) }}</div></td><td><div class="detail-cell-content">{{ item.contactName || '-' }}</div></td><td><div class="detail-cell-content"><span class="email-value">{{ item.recipientEmail || '-' }}</span><button v-if="item.recipientEmail" class="copy-email-button" type="button" @click="copyEmail(item.recipientEmail)">{{ text.copy }}</button></div></td><td><div class="detail-cell-content"><strong>{{ labelForCode(item.code) }}</strong><br>{{ item.message }}</div></td><td><div class="detail-cell-content">{{ item.hint || '-' }}</div></td><td class="action-cell"><button class="view-button" type="button" @click="selectedFailure = item">{{ text.view }}</button></td></tr></tbody></table><div v-if="totalFailurePages > 1" class="pagination"><button class="btn-xs" :disabled="failurePage <= 1" @click="loadFailures(failurePage - 1)">{{ text.previous }}</button><span>{{ failurePage }} / {{ totalFailurePages }}</span><button class="btn-xs" :disabled="failurePage >= totalFailurePages" @click="loadFailures(failurePage + 1)">{{ text.next }}</button></div></template></td></tr>
      <tr v-if="selectedRun?.runId === run.runId && selectedPanel === 'replies'"><td colspan="6" class="detail-cell"><div v-if="replyError" class="analysis-outreach-error" role="alert">{{ replyError }}</div><div v-if="replyLoading" class="email-automation-state">{{ text.loading }}</div><div v-else-if="!replies.length" class="email-automation-state">{{ text.noReply }}</div><template v-else><div class="detail-summary">{{ replyTotal }} {{ text.replyCount }}</div><table class="detail-table reply-table"><thead><tr><th>{{ text.company }}</th><th>{{ text.contact }}</th><th>{{ text.email }}</th><th>{{ text.content }}</th><th>{{ text.analysis }}</th><th class="action-cell">{{ text.action }}</th></tr></thead><tbody><tr v-for="item in replies" :key="item.emailId"><td><div class="detail-cell-content">{{ item.companyName || '-' }}</div></td><td><div class="detail-cell-content">{{ item.contactName || '-' }}</div></td><td><div class="detail-cell-content"><span class="email-value">{{ item.emailAddress || '-' }}</span><button v-if="item.emailAddress" class="copy-email-button" type="button" @click="copyEmail(item.emailAddress)">{{ text.copy }}</button></div></td><td><div class="detail-cell-content content-preview">{{ previewReplyContent(item.content) }}</div></td><td><div class="detail-cell-content"><template v-if="item.analysis.intentLevel === 'automatic_reply'"><strong class="intent-label">&#33258;&#21160;&#22238;&#22797;</strong></template><template v-else><strong class="intent-label">{{ formatReplyAnalysis(item.analysis).intent }}</strong><br>{{ formatReplyAnalysis(item.analysis).nextAction }}</template></div></td><td class="action-cell"><button class="view-button" type="button" @click="selectedReply = item">{{ text.view }}</button></td></tr></tbody></table><div v-if="totalReplyPages > 1" class="pagination"><button class="btn-xs" :disabled="replyPage <= 1" @click="loadReplies(replyPage - 1)">{{ text.previous }}</button><span>{{ replyPage }} / {{ totalReplyPages }}</span><button class="btn-xs" :disabled="replyPage >= totalReplyPages" @click="loadReplies(replyPage + 1)">{{ text.next }}</button></div></template></td></tr></template></tbody></table></div></section>
    <div v-if="selectedReply" class="reply-modal-backdrop" role="presentation" @click.self="selectedReply = null"><section class="reply-modal" role="dialog" aria-modal="true" :aria-label="text.view"><div class="reply-modal-header"><strong>{{ text.view }}</strong><button class="modal-close" type="button" :aria-label="text.close" @click="selectedReply = null">×</button></div><div class="reply-meta"><div><b>{{ text.company }}&#65306;</b>{{ selectedReply.companyName || '-' }}</div><div><b>{{ text.contact }}&#65306;</b>{{ selectedReply.contactName || '-' }}</div><div><b>{{ text.email }}&#65306;</b>{{ selectedReply.emailAddress || '-' }}</div><div><b>{{ text.receivedAt }}&#65306;</b>{{ selectedReply.receivedAt ? new Date(selectedReply.receivedAt).toLocaleString() : '-' }}</div><div><b>{{ text.subject }}&#65306;</b>{{ selectedReply.subject || '-' }}</div></div><div class="reply-body">{{ selectedReply.content || '-' }}</div><div class="reply-analysis"><b>{{ text.analysis }}</b><div>{{ text.intent }}&#65306;{{ formatReplyAnalysis(selectedReply.analysis).intent }}</div><div v-if="formatReplyAnalysis(selectedReply.analysis).nextAction">{{ text.nextAction }}&#65306;{{ formatReplyAnalysis(selectedReply.analysis).nextAction }}</div><div v-if="selectedReply.analysis.confidence != null">{{ text.confidence }}&#65306;{{ Math.round(selectedReply.analysis.confidence * 100) }}%</div><div v-if="formatReplyAnalysis(selectedReply.analysis).evidence">{{ text.evidence }}&#65306;{{ formatReplyAnalysis(selectedReply.analysis).evidence }}</div></div></section></div>
    <div v-if="selectedFailure" class="reply-modal-backdrop" role="presentation" @click.self="selectedFailure = null"><section class="reply-modal" role="dialog" aria-modal="true" :aria-label="text.view"><div class="reply-modal-header"><strong>{{ text.view }}</strong><button class="modal-close" type="button" :aria-label="text.close" @click="selectedFailure = null">&#215;</button></div><div class="reply-meta"><div><b>{{ text.company }}&#65306;</b>{{ displayFailureCompany(selectedFailure) }}</div><div><b>{{ text.contact }}&#65306;</b>{{ selectedFailure.contactName || '-' }}</div><div><b>{{ text.email }}&#65306;</b>{{ selectedFailure.recipientEmail || '-' }}</div><div><b>{{ text.reason }}&#65306;</b>{{ labelForCode(selectedFailure.code) }}</div><div><b>{{ text.content }}&#65306;</b>{{ selectedFailure.message || '-' }}</div><div><b>{{ text.hint }}&#65306;</b>{{ selectedFailure.hint || '-' }}</div><div><b>&#23581;&#35797;&#27425;&#25968;&#65306;</b>{{ selectedFailure.attempts || 0 }}</div></div></section></div>
  </div>
</template>
<style scoped>
.email-automation-page { max-width: 1400px; }.email-automation-header-actions { display: flex; align-items: center; gap: 12px; }.email-automation-close { width: 46px; height: 30px; box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center; padding: 3px 8px; color: var(--text-muted); font-size: 16px; line-height: 1; text-align: center; text-decoration: none; }.email-automation-state { padding: 24px; color: var(--text-muted); text-align: center; }.email-automation-runs { margin-top: 18px; }.count-button { min-width: 30px; border: 0; border-radius: 12px; padding: 3px 9px; cursor: pointer; }.has-failures { background: #fee2e2; color: #b91c1c; }.has-replies { background: #dcfce7; color: #15803d; }.zero-count { background: #f1f5f9; color: #64748b; cursor: default; }.detail-cell { width: 100%; padding: 0 !important; background: #f8fafc; }.detail-cell > .detail-summary, .detail-cell > .detail-table, .detail-cell > .email-automation-state, .detail-cell > .analysis-outreach-error, .detail-cell > .pagination { width: min(1280px, calc(100vw - 64px)); margin-left: auto; margin-right: auto; box-sizing: border-box; }.detail-summary { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 12px 0; color: var(--text-muted); }.failure-code-chip { border: 1px solid #fecaca; border-radius: 12px; padding: 4px 9px; background: #fff; color: #b91c1c; cursor: pointer; }.failure-code-chip.active { background: #b91c1c; color: #fff; }.detail-table { width: 100%; table-layout: fixed; border-collapse: collapse; font-size: 12px; } .detail-table tbody tr { height: 56px; } .detail-table tbody td { height: 56px; max-height: 56px; overflow: hidden; } .detail-cell-content { display: -webkit-box; height: 38px; max-height: 38px; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-height: 19px; overflow-wrap: anywhere; } .detail-table td.action-cell { padding-top: 9px; padding-bottom: 9px; } .detail-table td.action-cell > .view-button { display: inline-flex; }.detail-table th, .detail-table td { padding: 9px 12px; border-top: 1px solid var(--border); text-align: left; vertical-align: top; overflow-wrap: anywhere; }.detail-table th:nth-child(1), .detail-table td:nth-child(1) { width: 17%; }.detail-table th:nth-child(2), .detail-table td:nth-child(2) { width: 15%; }.detail-table th:nth-child(3), .detail-table td:nth-child(3) { width: 20%; }.detail-table th:nth-child(4), .detail-table td:nth-child(4) { width: 25%; }.detail-table th:nth-child(5), .detail-table td:nth-child(5) { width: 18%; }.detail-table th.action-cell, .detail-table td.action-cell { width: 7%; text-align: center; vertical-align: middle; white-space: nowrap; }.email-value { display: inline-block; max-width: 220px; overflow: hidden; text-overflow: ellipsis; vertical-align: middle; }.copy-email-button, .view-button { margin-left: 6px; border: 0; background: transparent; color: var(--blue); cursor: pointer; }.view-button { border: 1px solid var(--border); border-radius: 5px; padding: 4px 9px; }.content-preview { max-width: 360px; white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.45; }.intent-label { font-weight: 700; color: var(--text-main); }.pagination { display: flex; justify-content: flex-end; align-items: center; gap: 10px; padding: 12px; }.reply-modal-backdrop { position: fixed; z-index: 20; inset: 0; display: flex; align-items: center; justify-content: center; padding: 24px; background: rgb(15 23 42 / 45%); }.reply-modal { width: min(760px, 100%); max-height: 85vh; overflow: auto; border-radius: 10px; padding: 20px; background: var(--surface, #fff); box-shadow: 0 18px 55px rgb(15 23 42 / 25%); }.reply-modal-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }.modal-close { width: 30px; height: 30px; display: inline-flex; align-items: center; justify-content: center; border: 1px solid var(--border); border-radius: 5px; background: transparent; color: var(--text-main); font-size: 18px; cursor: pointer; }.reply-meta { display: grid; gap: 7px; padding-bottom: 16px; border-bottom: 1px solid var(--border); }.reply-body { margin: 16px 0; white-space: pre-wrap; line-height: 1.65; }.reply-analysis { display: grid; gap: 7px; padding: 14px; border-radius: 7px; background: #f8fafc; }.reply-analysis b { color: var(--text-main); }
</style>
